import{_ as a,c as t,o,a3 as n}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Add an applicant","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/recruitment/applicants/add-applicant.md","filePath":"master/human-resources/recruitment/applicants/add-applicant.md","lastUpdated":1791902625000}'),i={name:"master/human-resources/recruitment/applicants/add-applicant.md"};function s(r,e,l,p,c,d){return o(),t("div",null,e[0]||(e[0]=[n('<h1 id="add-an-applicant" tabindex="-1">Add an applicant <a class="header-anchor" href="#add-an-applicant" aria-label="Permalink to &quot;Add an applicant&quot;">​</a></h1><p>An applicant records that one person applied for one job. You create it by choosing a candidate. If the person is new to Aureus, you create the candidate on the spot. Aureus then opens the full applicant page so you can add the details.</p><blockquote><p><strong>In simple words:</strong> Pick the person, click <strong>Create</strong>, then fill in the rest on the page that opens.</p></blockquote><p>Open <code>Recruitments → Applications → Applicants</code> and click <strong>New Applicant</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Create the <a href="./../job-positions/job-positions.html">job position</a> the person applies for. You choose it on the applicant page after you create the record.</p></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Rahul Verma applies for <strong>Warehouse Supervisor</strong>. He is not in Aureus yet, so you create him as a candidate while adding the applicant.</p><ol><li>Open <code>Recruitments → Applications → Applicants</code>. Click <strong>New Applicant</strong>.</li></ol><ol start="2"><li>The <strong>Create Applicant</strong> window opens. It has one field, <strong>Candidate</strong>. Open the list and look for Rahul Verma. He is not there, so use the create option under the list.</li></ol><ol start="3"><li>Fill in the candidate form that opens: <ul><li><strong>Full Name:</strong> <code>Rahul Verma</code></li><li><strong>Email Address:</strong> <code>rahul.verma@example.com</code></li><li><strong>Phone Number:</strong> a phone number.</li></ul></li></ol><ol start="4"><li>Save the candidate. The window returns to <strong>Create Applicant</strong> with <strong>Rahul Verma</strong> selected.</li></ol><ol start="5"><li>Click <strong>Create</strong>. Aureus opens the <strong>Edit Applicant</strong> page. Continue with <a href="./process-applicant.html">Process an applicant</a> to choose the job position and the recruiter.</li></ol><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><ul><li><strong><em>Candidate:</em></strong> Required. Choose an existing candidate, or create one with the create option. The candidate form is described in <a href="./candidates.html">Candidates</a>.</li></ul><p>Everything else lives on the applicant page: <a href="./process-applicant.html#details-you-fill-in">job position</a>, recruiter, interviewers, tags, salary and source.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Search the candidate list before you create a new one. One person should have one candidate record.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>If the chosen candidate already has an applicant for your company, Aureus does not create a duplicate. It reopens the old application instead. The application becomes active again, the refuse reason is cleared, and you become the recruiter.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./process-applicant.html">Process an applicant</a></li><li><a href="./candidates.html">Candidates</a></li><li><a href="./applicant-list.html">Applicant list</a></li><li><a href="./../job-positions/job-positions.html">Job positions</a></li></ul>',20)]))}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
